209: bool TextRendererDirectWrite::Initialize() {
210:     auto& provider = static_cast<FontProviderDirectWrite&>(font_provider_);
211:     if (provider.GetType() != FontProviderType::kDirectWrite) {
212:         log_->e("TextRendererDirectWrite: Font provider must be FontProviderDirectWrite");
213:         return false;
214:     }
215: 
216:     // Retrieve IDWriteFactory from FontProviderDirectWrite
217:     dwrite_factory_ = provider.GetDWriteFactory();
218:     if (!dwrite_factory_) {
219:         log_->e("TextRendererDirectWrite: FontProviderDirectWrite::GetDWriteFactory() returns nullptr");
220:         return false;
221:     }
222: 
223:     // Create IWICImagingFactory
224:     HRESULT hr = CoCreateInstance(CLSID_WICImagingFactory,
225:                                   nullptr,
226:                                   CLSCTX_INPROC_SERVER,
227:                                   IID_PPV_ARGS(&wic_factory_));
228:     if (FAILED(hr)) {
229:         log_->e("TextRendererDirectWrite: CoCreateInstance for CLSID_WICImagingFactory failed");
230:         return false;
231:     }
232: 
233:     // Create ID2D1Factory
234:     D2D1_FACTORY_OPTIONS d2d1_options = {D2D1_DEBUG_LEVEL_ERROR};
235: #ifndef NDEBUG
236:     d2d1_options.debugLevel = D2D1_DEBUG_LEVEL_INFORMATION;
237: #endif
238:     hr = D2D1CreateFactory(D2D1_FACTORY_TYPE_MULTI_THREADED, d2d1_options, d2d_factory_.GetAddressOf());
239:     if (FAILED(hr)) {
240:         log_->e("TextRendererDirectWrite: D2D1CreateFactory() failed");
241:         return false;
242:     }
243: 
244:     // Create d2d stroke style for outline stroke
245:     hr = d2d_factory_->CreateStrokeStyle(
246:         D2D1::StrokeStyleProperties(
247:             D2D1_CAP_STYLE_ROUND,
248:             D2D1_CAP_STYLE_ROUND,
249:             D2D1_CAP_STYLE_ROUND,
250:             D2D1_LINE_JOIN_ROUND,
251:             10.0f,
252:             D2D1_DASH_STYLE_SOLID,
253:             0.0f),
254:         nullptr,
255:         0,
256:         &stroke_style_);
257:     if (FAILED(hr)) {
258:         log_->e("TextRendererDirectWrite: ID2D1Factory::CreateStrokeStyle() failed");
259:         return false;
260:     }
261: 
262:     return true;
263: }
