291: auto TextRendererDirectWrite::BeginDraw(Bitmap& target_bmp) -> TextRenderContext {
292:     auto priv = std::make_unique<TextRenderContextPrivateDirectWrite>();
293:     // Create WIC bitmap
294:     HRESULT hr = wic_factory_->CreateBitmap(static_cast<UINT>(target_bmp.width()),
295:                                             static_cast<UINT>(target_bmp.height()),
296:                                             GUID_WICPixelFormat32bppPRGBA,
297:                                             WICBitmapCreateCacheOption::WICBitmapCacheOnLoad,
298:                                             &priv->wic_bitmap);
299:     if (FAILED(hr)) {
300:         log_->e("TextRendererDirectWrite: Allocate IWICBitmap failed");
301:         return TextRenderContext(target_bmp);
302:     }
303: 
304:     // Create WIC-target Direct2D render target
305:     priv->d2d_render_target = CreateWICRenderTarget(priv->wic_bitmap.Get());
306:     if (!priv->d2d_render_target) {
307:         log_->e("TextRendererDirectWrite: Create WIC ID2D1RenderTarget failed");
308:         return TextRenderContext(target_bmp);
309:     }
310: 
311:     priv->d2d_render_target->BeginDraw();
312:     priv->d2d_render_target->Clear();
313:     priv->d2d_render_target->SetAntialiasMode(D2D1_ANTIALIAS_MODE_PER_PRIMITIVE);
314:     priv->d2d_render_target->SetTextAntialiasMode(D2D1_TEXT_ANTIALIAS_MODE_CLEARTYPE);
315: 
316:     return TextRenderContext{target_bmp, std::move(priv)};
317: }
