319: void TextRendererDirectWrite::EndDraw(TextRenderContext& context) {
320:     auto priv = static_cast<TextRenderContextPrivateDirectWrite*>(context.GetPrivate());
321: 
322:     HRESULT hr = priv->d2d_render_target->EndDraw();
323:     if (FAILED(hr)) {
324:         log_->e("TextRendererDirectWrite: ID2D1RenderTarget::EndDraw() returned error");
325:     }
326:     priv->d2d_render_target.Reset();
327: 
328:     bool result = BlendWICBitmapToBitmap(priv->wic_bitmap.Get(), context.GetBitmap(), 0, 0);
329:     if (!result) {
330:         log_->e("TextRendererDirectWrite: BlendWICBitmapToBitmap() failed");
331:     }
332:     priv->wic_bitmap.Reset();
