335: auto TextRendererDirectWrite::DrawChar(TextRenderContext& render_ctx, int target_x, int target_y,
336:                                        uint32_t ucs4, CharStyle style, ColorRGBA color, ColorRGBA stroke_color,
337:                                        float stroke_width, int char_width, int char_height, float aspect_ratio,
338:                                        std::optional<UnderlineInfo> underline_info,
339:                                        TextRenderFallbackPolicy fallback_policy) -> TextRenderStatus {
340:     if (!render_ctx.GetPrivate()) {
341:         log_->e("TextRendererDirectWrite: Invalid TextRenderContext, BeginDraw() failed or not called");
342:         return TextRenderStatus::kOtherError;
343:     }
344: 
345:     assert(char_height > 0);
346:     if (stroke_width < 0.0f) {
347:         stroke_width = 0.0f;
348:     }
349: 
350:     // Skip space characters
351:     if (unicode::IsSpaceCharacter(ucs4)) {
352:         return TextRenderStatus::kOK;
353:     }
354: 
355:     // Load main font if not loaded
356:     if (!main_faceinfo_) {
357:         auto result = LoadDWriteFont();
358:         if (result.is_err()) {
359:             log_->e("TextRendererDirectWrite: Cannot find valid font");
360:             return FontProviderErrorToStatus(result.error());
361:         }
362:         auto& pair = result.value();
363:         main_faceinfo_ = std::move(pair.first);
364:         main_face_index_ = pair.second;
365:     }
366: 
367:     // Setup IDWriteTextFormat for main font
368:     if (!main_text_format_ || char_height != main_text_format_pixel_height_) {
369:         main_text_format_pixel_height_ = char_height;
370:         main_text_format_ = CreateDWriteTextFormat(main_faceinfo_.value(), char_height);
371:         if (!main_text_format_) {
372:             log_->e("TextRendererDirectWrite: Create IDWriteTextFormat failed");
373:             return TextRenderStatus::kOtherError;
374:         }
375:     }
376: 
377:     FontfaceInfo* face_info = &main_faceinfo_.value();
378:     IDWriteTextFormat* text_format = main_text_format_.Get();
379: 
380:     // If codepoint was not found in main font, load fallback font
381:     if (!FontfaceHasCharacter(main_faceinfo_.value(), ucs4)) {
382:         log_->w("TextRendererDirectWrite: Main font %s doesn't contain U+%04X",
383:                 main_faceinfo_.value().family_name.c_str(), ucs4);
384: 
385:         if (fallback_policy == TextRenderFallbackPolicy::kFailOnCodePointNotFound) {
386:             return TextRenderStatus::kCodePointNotFound;
387:         }
388: 
389:         if (main_face_index_ + 1 >= font_family_.size()) {
390:             // Fallback fonts not available
391:             return TextRenderStatus::kCodePointNotFound;
392:         }
393: 
394:         bool reset_fallback_text_format = false;
395:         // Check fallback faceinfo
396:         if (!fallback_faceinfo_ || !FontfaceHasCharacter(fallback_faceinfo_.value(), ucs4)) {
397:             // Fallback font not loaded, or doesn't contain required codepoint
398:             auto result = LoadDWriteFont(ucs4, main_face_index_ + 1);
399:             if (result.is_err()) {
400:                 log_->e("TextRendererDirectWrite: Cannot find available fallback font for U+%04X", ucs4);
401:                 return FontProviderErrorToStatus(result.error());
402:             }
403:             auto& pair = result.value();
404:             fallback_faceinfo_ = std::move(pair.first);
405:             reset_fallback_text_format = true;
406:         }
407: 
408:         // Setup IDWriteTextFormat for fallback font
409:         if (!fallback_text_format_ ||
410:             char_height != fallback_text_format_pixel_height_ ||
411:             reset_fallback_text_format) {
412:             fallback_text_format_pixel_height_ = char_height;
413:             fallback_text_format_ = CreateDWriteTextFormat(fallback_faceinfo_.value(), char_height);
414:             if (!fallback_text_format_) {
415:                 log_->e("TextRendererDirectWrite: Create fallback IDWriteTextFormat failed");
416:                 return TextRenderStatus::kOtherError;
417:             }
418:         }
419: 
420:         face_info = &fallback_faceinfo_.value();
421:         text_format = fallback_text_format_.Get();
422:     }
423: 
424:     std::u16string wide_char;
425:     utf::UTF16AppendCodePoint(wide_char, ucs4);
426: 
427:     // Create DirectWrite TextLayout
428:     ComPtr<IDWriteTextLayout> text_layout;
429:     HRESULT hr = dwrite_factory_->CreateTextLayout(reinterpret_cast<WCHAR*>(wide_char.data()),
430:                                                    static_cast<UINT32>(wide_char.length()),
431:                                                    text_format, 16384.0f, 16384.0f, &text_layout);
432:     if (FAILED(hr) || !text_layout) {
433:         log_->e("TextRendererDirectWrite: Create IDWriteTextLayout failed");
434:         return TextRenderStatus::kOtherError;
435:     }
436: 
437:     // Set underline property if required
438:     if (style & CharStyle::kCharStyleUnderline) {
439:         text_layout->SetUnderline(TRUE, DWRITE_TEXT_RANGE{0, 1});
440:     }
441: 
442:     // Get font's metrics
443:     auto face_info_priv = static_cast<FontfaceInfoPrivateDirectWrite*>(face_info->provider_priv.get());
444:     DWRITE_FONT_METRICS font_metrics = {0};
