554: auto TextRendererDirectWrite::LoadDWriteFont(std::optional<uint32_t> codepoint,
555:                                              std::optional<size_t> begin_index)
556:     -> Result<std::pair<FontfaceInfo, size_t>, FontProviderError> {
557:     if (begin_index && begin_index.value() >= font_family_.size()) {
558:         return Err(FontProviderError::kFontNotFound);
559:     }
560: 
561:     // begin_index is optional
562:     size_t font_index = begin_index.value_or(0);
563: 
564:     const std::string& font_name = font_family_[font_index];
565:     auto result = font_provider_.GetFontFace(font_name, codepoint);
566: 
567:     while (result.is_err() && font_index + 1 < font_family_.size()) {
568:         // Find next suitable font
569:         font_index++;
570:         result = font_provider_.GetFontFace(font_family_[font_index], codepoint);
571:     }
572:     if (result.is_err()) {
573:         // Not found, return Err Result
574:         return Err(result.error());
575:     }
576: 
577:     FontfaceInfo& info = result.value();
578:     if (info.provider_type != FontProviderType::kDirectWrite) {
579:         log_->e("TextRendererDirectWrite: Font provider must be FontProviderDirectWrite");
580:         return Err(FontProviderError::kOtherError);
581:     }
582: 
583:     return Ok(std::make_pair(std::move(info), font_index));
584: }
