97: auto TextRendererCoreText::DrawChar(TextRenderContext& render_ctx, int target_x, int target_y,
98:                                     uint32_t ucs4, CharStyle style, ColorRGBA color, ColorRGBA stroke_color,
99:                                     float stroke_width, int char_width, int char_height, float aspect_ratio,
100:                                     std::optional<UnderlineInfo> underline_info,
101:                                     TextRenderFallbackPolicy fallback_policy) -> TextRenderStatus {
102:     if (!render_ctx.GetPrivate()) {
103:         log_->e("TextRendererCoreText: Invalid TextRenderContext, BeginDraw() failed or not called");
104:         return TextRenderStatus::kOtherError;
105:     }
106: 
107:     assert(char_height > 0);
108:     if (stroke_width < 0.0f) {
109:         stroke_width = 0.0f;
110:     }
111: 
112:     // Skip space characters
113:     if (unicode::IsSpaceCharacter(ucs4)) {
114:         return TextRenderStatus::kOK;
115:     }
116: 
117:     // Load main CTFont if not loaded
118:     if (!main_ctfont_) {
119:         auto result = LoadCTFont();
120:         if (result.is_err()) {
121:             log_->e("TextRendererCoreText: Cannot find valid font");
122:             return FontProviderErrorToStatus(result.error());
123:         }
124:         std::pair<ScopedCFRef<CTFontRef>, size_t>& pair = result.value();
125:         main_ctfont_ = std::move(pair.first);
126:         main_face_index_ = pair.second;
127:     }
128: 
129:     // Build size-specified main CTFont
130:     if (!main_ctfont_sized_ || char_height != main_ctfont_pixel_height_) {
131:         main_ctfont_pixel_height_ = char_height;
132:         main_ctfont_sized_ = CreateSizedCTFont(main_ctfont_.get(), char_height);
133:         if (!main_ctfont_sized_) {
134:             log_->e("TextRendererCoreText: Create sized CTFont failed");
135:             return TextRenderStatus::kOtherError;
136:         }
137:     }
138: 
139:     CTFontRef ctfont = main_ctfont_sized_.get();
140: 
141:     std::u16string utf16;
142:     size_t codeunit_count = utf::UTF16AppendCodePoint(utf16, ucs4);
143:     CGGlyph glyphs[2] = {0};
144:     bool has_glyph = CTFontGetGlyphsForCharacters(ctfont,
145:                                                   reinterpret_cast<UniChar*>(utf16.data()),
146:                                                   glyphs,
147:                                                   static_cast<CFIndex>(codeunit_count));
148: 
149:     // Check whether codepoint exists in main CTFont, otherwise load fallback CTFont
150:     if (!has_glyph) {
151:         ScopedCFRef<CFStringRef> cf_main_family_name(CTFontCopyFamilyName(ctfont));
152:         std::string main_family_name = cfstr::CFStringToStdString(cf_main_family_name.get());
153:         log_->w("TextRendererCoreText: Main font %s doesn't contain U+%04X", main_family_name.c_str(), ucs4);
154: 
155:         if (fallback_policy == TextRenderFallbackPolicy::kFailOnCodePointNotFound) {
156:             return TextRenderStatus::kCodePointNotFound;
157:         }
158: 
159:         if (main_face_index_ + 1 >= font_family_.size()) {
160:             // Fallback fonts not available
161:             return TextRenderStatus::kCodePointNotFound;
162:         }
163: 
164:         bool reset_sized_fallback = false;
165:         // Missing glyph, check fallback CTFont
166:         if (!fallback_ctfont_ || !CTFontGetGlyphsForCharacters(fallback_ctfont_.get(),
167:                                                                reinterpret_cast<UniChar*>(utf16.data()),
168:                                                                glyphs,
169:                                                                static_cast<CFIndex>(codeunit_count))) {
170:             // Fallback CTFont not loaded, or fallback CTFont doesn't contain required codepoint
171:             // Load next fallback CTFont by specific codepoint
172:             auto result = LoadCTFont(ucs4, main_face_index_ + 1);
173:             if (result.is_err()) {
174:                 log_->e("TextRendererCoreText: Cannot find available fallback font for U+%04X", ucs4);
175:                 return FontProviderErrorToStatus(result.error());
176:             }
177:             std::pair<ScopedCFRef<CTFontRef>, size_t>& pair = result.value();
178:             fallback_ctfont_ = std::move(pair.first);
179:             reset_sized_fallback = true;
180:         }
181: 
182:         // Build size-specified fallback CTFont
183:         if (!fallback_ctfont_sized_ || char_height != fallback_ctfont_pixel_height_ || reset_sized_fallback) {
184:             fallback_ctfont_pixel_height_ = char_height;
185:             fallback_ctfont_sized_ = CreateSizedCTFont(fallback_ctfont_.get(), char_height);
186:             if (!fallback_ctfont_sized_) {
187:                 log_->e("TextRendererCoreText: Create sized fallback CTFont failed");
188:                 return TextRenderStatus::kOtherError;
189:             }
190:         }
191: 
192:         ctfont = fallback_ctfont_sized_.get();
193:     }
194: 
195:     // Re-retrieve glyph from sized CTFont
196:     CTFontGetGlyphsForCharacters(ctfont,
197:                                  reinterpret_cast<UniChar*>(utf16.data()),
198:                                  glyphs,
199:                                  static_cast<CFIndex>(codeunit_count));
200: 
201:     CGFloat ascent = CTFontGetAscent(ctfont);
202:     CGFloat descent = CTFontGetDescent(ctfont);
203:     CGFloat em_height = ascent + descent;
204: 
205:     CGFloat em_adjust_y = (static_cast<CGFloat>(char_height) - em_height) / 2.0f;
206:     CGFloat charbox_bottom = render_ctx.GetBitmap().height() - (target_y + char_height);
207:     CGFloat baseline_y = std::round(charbox_bottom + descent + em_adjust_y);
208: 
209:     CGFloat underline_pos = CTFontGetUnderlinePosition(ctfont);
210:     CGFloat underline_thickness = CTFontGetUnderlineThickness(ctfont);
211: 
212:     auto render_ctx_priv = static_cast<TextRenderContextPrivateCoreText*>(render_ctx.GetPrivate());
213:     const ScopedCFRef<CGContextRef>& ctx = render_ctx_priv->cg_context;
214: 
215:     CGContextSaveGState(ctx.get());
216: 
217:     // Draw Underline if required
218:     if ((style & kCharStyleUnderline) && underline_info && underline_thickness > 0.0f) {
219:         CGFloat underline_y = baseline_y + underline_pos;
220:         ScopedCFRef<CGColorRef> cg_underline_color = RGBAToCGColor(color);
221:         CGContextSetStrokeColorWithColor(ctx.get(), cg_underline_color.get());
222:         CGContextSetLineWidth(ctx.get(), underline_thickness);
223: 
224:         CGContextMoveToPoint(ctx.get(), underline_info->start_x, underline_y);
225:         CGContextAddLineToPoint(ctx.get(), underline_info->start_x + underline_info->width, underline_y);
226:         CGContextStrokePath(ctx.get());
227:     }
228: 
229:     CGPoint origin = CGPointMake(target_x, baseline_y);
230: 
231:     // Check if it is MSZ (Middle Size)
232:     bool is_requesting_halfwidth = floating::AlmostEquals(aspect_ratio, 0.5f, 0.05f);
233:     bool needless_horizontal_scaling = is_requesting_halfwidth && unicode::IsHalfwidthCharacter(ucs4);
234: 
235:     // Scale character correctly if char_width is different from char_height
236:     // Do not do horizontal scaling if the character is halfwidth already
237:     if (char_width != char_height && !needless_horizontal_scaling) {
238:         CGFloat horizontal_scale = static_cast<CGFloat>(char_width) / static_cast<CGFloat>(char_height);
239:         CGContextTranslateCTM(ctx.get(), origin.x, origin.y);
240:         CGContextScaleCTM(ctx.get(), horizontal_scale, 1.0f);
241:         CGContextTranslateCTM(ctx.get(), -origin.x, -origin.y);
242:     }
243: 
244:     // Draw stroke border if required
245:     if (style & CharStyle::kCharStyleStroke && stroke_width > 0.0f) {
246:         CGAffineTransform path_matrix = CGAffineTransformMakeTranslation(origin.x, origin.y);
247:         ScopedCFRef<CGPathRef> path(CTFontCreatePathForGlyph(ctfont, glyphs[0], &path_matrix));
248:         CGContextAddPath(ctx.get(), path.get());
249: 
250:         ScopedCFRef<CGColorRef> cg_stroke_color = RGBAToCGColor(stroke_color);
251:         CGContextSetStrokeColorWithColor(ctx.get(), cg_stroke_color.get());
252:         CGContextSetLineWidth(ctx.get(), stroke_width * 2);
253:         CGContextSetLineCap(ctx.get(), kCGLineCapRound);
254:         CGContextSetLineJoin(ctx.get(), kCGLineJoinRound);
255:         CGContextStrokePath(ctx.get());
256:     }
257: 
258:     // Draw character (fill)
259:     ScopedCFRef<CGColorRef> cg_fill_color = RGBAToCGColor(color);
260:     CGContextSetFillColorWithColor(ctx.get(), cg_fill_color.get());
261:     CTFontDrawGlyphs(ctfont, &glyphs[0], &origin, 1, ctx.get());
262: 
263:     CGContextRestoreGState(ctx.get());
264: 
265:     return TextRenderStatus::kOK;
266: }
