268: auto TextRendererCoreText::LoadCTFont(std::optional<uint32_t> codepoint, std::optional<size_t> begin_index)
269:         -> Result<std::pair<ScopedCFRef<CTFontRef>, size_t>, FontProviderError> {
270:     if (begin_index && begin_index.value() >= font_family_.size()) {
271:         return Err(FontProviderError::kFontNotFound);
272:     }
273: 
274:     // begin_index is optional
275:     size_t font_index = begin_index.value_or(0);
276: 
277:     const std::string& font_name = font_family_[font_index];
278:     auto result = font_provider_.GetFontFace(font_name, codepoint);
279: 
280:     while (result.is_err() && font_index + 1 < font_family_.size()) {
281:         // Find next suitable font
282:         font_index++;
283:         result = font_provider_.GetFontFace(font_family_[font_index], codepoint);
284:     }
285:     if (result.is_err()) {
286:         // Not found, return Err Result
287:         return Err(result.error());
288:     }
289: 
290:     FontfaceInfo& info = result.value();
291:     if (info.provider_type != FontProviderType::kCoreText) {
292:         log_->e("TextRendererCoreText: Font provider must be FontProviderCoreText");
293:         return Err(FontProviderError::kOtherError);
294:     }
295: 
296:     auto priv = static_cast<FontfaceInfoPrivateCoreText*>(info.provider_priv.get());
297: 
298:     return Ok(std::make_pair(std::move(priv->ct_font), font_index));
299: }
