104: auto TextRendererFreetype::DrawChar(TextRenderContext& render_ctx, int target_x, int target_y,
105:                                     uint32_t ucs4, CharStyle style, ColorRGBA color, ColorRGBA stroke_color,
106:                                     float stroke_width, int char_width, int char_height, float aspect_ratio,
107:                                     std::optional<UnderlineInfo> underline_info,
108:                                     TextRenderFallbackPolicy fallback_policy) -> TextRenderStatus {
109:     assert(char_height > 0);
110:     if (stroke_width < 0.0f) {
111:         stroke_width = 0.0f;
112:     }
113: 
114:     // Skip space characters
115:     if (unicode::IsSpaceCharacter(ucs4)) {
116:         return TextRenderStatus::kOK;
117:     }
118: 
119:     if (!main_face_) {
120:         // If main FT_Face is not yet loaded, try load FT_Face from font_family_
121:         // We don't care about the codepoint (ucs4) now
122:         auto result = LoadFontFace(false);
123:         if (result.is_err()) {
124:             log_->e("Freetype: Cannot find valid font");
125:             return FontProviderErrorToStatus(result.error());
126:         }
127:         std::pair<FT_Face, size_t>& pair = result.value();
128:         main_face_ = ScopedHolder<FT_Face>(pair.first, FT_Done_Face);
129:         main_face_index_ = pair.second;
130:     }
131: 
132:     FT_Face face = main_face_;
133:     FT_UInt glyph_index = FT_Get_Char_Index(face, ucs4);
134: 
135:     if (glyph_index == 0) {
136:         log_->w("Freetype: Main font %s doesn't contain U+%04X", face->family_name, ucs4);
137: 
138:         if (fallback_policy == TextRenderFallbackPolicy::kFailOnCodePointNotFound) {
139:             return TextRenderStatus::kCodePointNotFound;
140:         }
141: 
142:         // Missing glyph, check fallback face
143:         if (fallback_face_ && (glyph_index = FT_Get_Char_Index(fallback_face_, ucs4))) {
144:             face = fallback_face_;
145:         } else if (main_face_index_ + 1 >= font_family_.size()) {
146:             // Fallback fonts not available
147:             return TextRenderStatus::kCodePointNotFound;
148:         } else {
149:             // Fallback fontface not loaded, or fallback fontface doesn't contain required codepoint
150:             // Load next fallback font face by specific codepoint
151:             auto result = LoadFontFace(true, ucs4, main_face_index_ + 1);
152:             if (result.is_err()) {
153:                 log_->e("Freetype: Cannot find available fallback font for U+%04X", ucs4);
154:                 return FontProviderErrorToStatus(result.error());
155:             }
156:             std::pair<FT_Face, size_t>& pair = result.value();
157:             fallback_face_ = ScopedHolder<FT_Face>(pair.first, FT_Done_Face);
158: 
159:             // Use this fallback fontface for rendering this time
160:             face = fallback_face_;
161:             glyph_index = FT_Get_Char_Index(face, ucs4);
162:             if (glyph_index == 0) {
163:                 log_->e("Freetype: Got glyph_index == 0 for U+%04X in fallback font", ucs4);
164:                 return TextRenderStatus::kCodePointNotFound;
165:             }
166:         }
167:     }
168: 
169:     // If aspect_ratio is 0.5 (1:2), this should be MSZ (Middle size)
170:     bool is_requesting_halfwidth = floating::AlmostEquals(aspect_ratio, 0.5f, 0.05f);
171:     if (is_requesting_halfwidth && unicode::IsHalfwidthCharacter(ucs4)) {
172:         // Do not do horizontal scaling since the character is halfwidth already
173:         char_width = char_height;
174:     }
175: 
176:     if (replace_msz_halfwidth_glyph_ && is_requesting_halfwidth) {
177:         if (face == main_face_) {
178:             if (!main_halfwidth_subst_map_) {
179:                 main_halfwidth_subst_map_ =
180:                     LoadSingleGSUBTable(LoadSFNTTable(face, FT_MAKE_TAG('G', 'S', 'U', 'B')), kOpenTypeFeatureHalfWidth,
181:                                         kOpenTypeScriptHiraganaKatakana, kOpenTypeLangSysJapanese);
182:             }
183:         } else if (fallback_face_ && face == fallback_face_) {
184:             if (!fallback_halfwidth_subst_map_) {
185:                 fallback_halfwidth_subst_map_ =
186:                     LoadSingleGSUBTable(LoadSFNTTable(face, FT_MAKE_TAG('G', 'S', 'U', 'B')), kOpenTypeFeatureHalfWidth,
187:                                         kOpenTypeScriptHiraganaKatakana, kOpenTypeLangSysJapanese);
188:             }
189:         }
190:         auto& subst_map = face == main_face_ ? main_halfwidth_subst_map_ : fallback_halfwidth_subst_map_;
191:         if (subst_map) {
192:             auto subst = subst_map->find(glyph_index);
193:             if (subst != subst_map->end()) {
194:                 glyph_index = subst->second;
195:                 char_width = char_height;
196:             }
197:         }
198:     }
199: 
200:     if (FT_Set_Pixel_Sizes(face, static_cast<FT_UInt>(char_width), static_cast<FT_UInt>(char_height))) {
201:         log_->e("Freetype: FT_Set_Pixel_Sizes failed");
202:         return TextRenderStatus::kOtherError;
203:     }
204: 
205:     int baseline = static_cast<int>(face->size->metrics.ascender >> 6);
206:     int ascender = static_cast<int>(face->size->metrics.ascender >> 6);
207:     int descender = static_cast<int>(face->size->metrics.descender >> 6);
208:     int underline = static_cast<int>(FT_MulFix(face->underline_position, face->size->metrics.x_scale) >> 6);
209:     int underline_thickness = static_cast<int>(FT_MulFix(face->underline_thickness, face->size->metrics.x_scale) >> 6);
210: 
211:     int em_height = ascender + std::abs(descender);
212:     int em_adjust_y = (char_height - em_height) / 2;
213: 
214:     if (FT_Load_Glyph(face, glyph_index, FT_LOAD_NO_BITMAP)) {
215:         log_->e("Freetype: FT_Load_Glyph failed");
216:         return TextRenderStatus::kOtherError;
217:     }
218: 
219:     // Generate glyph bitmap for filling
220:     ScopedHolder<FT_Glyph> glyph_image(nullptr, FT_Done_Glyph);
221:     if (FT_Get_Glyph(face->glyph, &glyph_image)) {
222:         log_->e("Freetype: FT_Get_Glyph failed");
223:         return TextRenderStatus::kOtherError;
224:     }
225: 
226:     if (FT_Glyph_To_Bitmap(&glyph_image, FT_RENDER_MODE_NORMAL, nullptr, true)) {
227:         log_->e("Freetype: FT_Glyph_To_Bitmap failed");
228:         return TextRenderStatus::kOtherError;
229:     }
230: 
231:     ScopedHolder<FT_Glyph> border_glyph_image(nullptr, FT_Done_Glyph);
232: 
233:     // If we need stroke text (border)
234:     if (style & CharStyle::kCharStyleStroke && stroke_width > 0.0f) {
235:         // Generate glyph bitmap for stroke border
236:         ScopedHolder<FT_Glyph> stroke_glyph(nullptr, FT_Done_Glyph);
237:         if (FT_Get_Glyph(face->glyph, &stroke_glyph)) {
238:             log_->e("Freetype: FT_Get_Glyph failed");
239:             return TextRenderStatus::kOtherError;
240:         }
241: 
242:         ScopedHolder<FT_Stroker> stroker(nullptr, FT_Stroker_Done);
243:         FT_Stroker_New(library_, &stroker);
244:         FT_Stroker_Set(stroker,
245:                        static_cast<FT_Fixed>(stroke_width * 64),
246:                        FT_STROKER_LINECAP_ROUND,
247:                        FT_STROKER_LINEJOIN_ROUND,
248:                        0);
249: 
250:         FT_Glyph_StrokeBorder(&stroke_glyph, stroker, false, true);
251: 
252:         if (FT_Glyph_To_Bitmap(&stroke_glyph, FT_RENDER_MODE_NORMAL, nullptr, true)) {
253:             log_->e("Freetype: FT_Glyph_To_Bitmap failed");
254:             return TextRenderStatus::kOtherError;
255:         }
256: 
257:         border_glyph_image = std::move(stroke_glyph);
258:     }
259: 
260:     Canvas canvas(render_ctx.GetBitmap());
261: 
262:     // Draw Underline if required
263:     if ((style & kCharStyleUnderline) && underline_info && underline_thickness > 0) {
264:         int underline_y = target_y + baseline + em_adjust_y + std::abs(underline);
265:         Rect underline_rect(underline_info->start_x,
266:                             underline_y,
267:                             underline_info->start_x + underline_info->width,
268:                             underline_y + 1);
269: 
270:         int half_thickness = underline_thickness / 2;
271: 
272:         if (underline_thickness % 2) {  // odd number
273:             underline_rect.top -= half_thickness;
274:             underline_rect.bottom += half_thickness;
275:         } else {  // even number
276:             underline_rect.top -= half_thickness - 1;
277:             underline_rect.bottom += half_thickness;
278:         }
279: 
280:         canvas.DrawRect(color, underline_rect);
281:     }
282: 
283:     // Draw stroke border bitmap, if required
284:     if (border_glyph_image) {
285:         auto border_bitmap_glyph = reinterpret_cast<FT_BitmapGlyph>(border_glyph_image.Get());
286:         int start_x = target_x + border_bitmap_glyph->left;
287:         int start_y = target_y + baseline + em_adjust_y - border_bitmap_glyph->top;
288: 
289:         Bitmap bmp = FTBitmapToColoredBitmap(border_bitmap_glyph->bitmap, stroke_color);
290:         canvas.DrawBitmap(bmp, start_x, start_y);
291:     }
292: 
293:     // Draw filling bitmap
294:     if (glyph_image) {
295:         auto bitmap_glyph = reinterpret_cast<FT_BitmapGlyph>(glyph_image.Get());
296:         int start_x = target_x + bitmap_glyph->left;
297:         int start_y = target_y + baseline + em_adjust_y - bitmap_glyph->top;
298: 
299:         Bitmap bmp = FTBitmapToColoredBitmap(bitmap_glyph->bitmap, color);
300:         canvas.DrawBitmap(bmp, start_x, start_y);
301:     }
302: 
303:     return TextRenderStatus::kOK;
304: }
