306: Bitmap TextRendererFreetype::FTBitmapToColoredBitmap(const FT_Bitmap& ft_bmp, ColorRGBA color) {
307:     Bitmap bitmap(static_cast<int>(ft_bmp.width), static_cast<int>(ft_bmp.rows), PixelFormat::kRGBA8888);
308: 
309:     for (uint32_t y = 0; y < ft_bmp.rows; y++) {
310:         uint32_t src_index = y * ft_bmp.pitch;
311:         const uint8_t* src = &ft_bmp.buffer[src_index];
312:         ColorRGBA* dest = bitmap.GetPixelAt(0, static_cast<int>(y));
313: 
314:         alphablend::FillLineWithAlphas(dest, src, color, ft_bmp.width);
315:     }
316: 
317:     return bitmap;
318: }
