320: static bool MatchFontFamilyName(FT_Face face, const std::string& family_name) {
321:     FT_UInt sfnt_name_count = FT_Get_Sfnt_Name_Count(face);
322: 
323:     for (FT_UInt i = 0; i < sfnt_name_count; i++) {
324:         FT_SfntName sfnt_name{};
325: 
326:         if (FT_Get_Sfnt_Name(face, i, &sfnt_name)) {
327:             continue;
328:         }
329: 
330:         if (sfnt_name.name_id == TT_NAME_ID_FONT_FAMILY || sfnt_name.name_id == TT_NAME_ID_FULL_NAME) {
331:             std::string name_str;
332:             if (sfnt_name.platform_id == TT_PLATFORM_MICROSOFT) {
333:                 name_str = utf::ConvertUTF16BEToUTF8(reinterpret_cast<uint16_t*>(sfnt_name.string),
334:                                                      sfnt_name.string_len / 2);
335:             } else {
336:                 name_str = std::string(sfnt_name.string, sfnt_name.string + sfnt_name.string_len);
337:             }
338:             if (name_str == family_name) {
339:                 return true;
340:             }
341:         }
342:     }
343: 
344:     return false;
345: }
