347: auto TextRendererFreetype::LoadFontFace(bool is_fallback,
348:                                         std::optional<uint32_t> codepoint,
349:                                         std::optional<size_t> begin_index)
350:         -> Result<std::pair<FT_Face, size_t>, FontProviderError> {
351:     if (begin_index && begin_index.value() >= font_family_.size()) {
352:         return Err(FontProviderError::kFontNotFound);
353:     }
354: 
355:     // begin_index is optional
356:     size_t font_index = begin_index.value_or(0);
357: 
358:     const std::string& font_name = font_family_[font_index];
359:     auto result = font_provider_.GetFontFace(font_name, codepoint);
360: 
361:     while (result.is_err() && font_index + 1 < font_family_.size()) {
362:         // Find next suitable font
363:         font_index++;
364:         result = font_provider_.GetFontFace(font_family_[font_index], codepoint);
365:     }
366:     if (result.is_err()) {
367:         // Not found, return Err Result
368:         return Err(result.error());
369:     }
370: 
371:     FontfaceInfo& info = result.value();
