264:         log_->v("FontProviderAndroid: Open %s failed", xml_path);
265:         return false;
266:     }
267: 
268:     XMLElement* root = doc.RootElement();
269:     if (strcmp(root->Name(), "familyset") != 0) {
270:         log_->e("FontProviderAndroid: Root element must be familyset, found %s", root->Name());
271:         return false;
272:     }
273: 
274:     const XMLAttribute* version_attr = root->FindAttribute("version");
275:     if (version_attr && version_attr->UnsignedValue() >= 21) {
276:         return HandleFamilySetLMP(root);
277:     } else {
278:         return HandleFamilySetOLD(root);
279:     }
